src='''def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v in (2, 3, 6, 8):
                continue
            counts = {}
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    rr, cc = r + dr, c + dc
                    if (dr or dc) and 0 <= rr < h and 0 <= cc < w:
                        color = grid[rr][cc]
                        if color in (2, 3, 6, 8):
                            counts[color] = counts.get(color, 0) + 1
            if counts:
                out[r][c] = max(counts, key=lambda color: counts[color])
    # Isolated stray cells in the background and the two large object colors
    # are repaired by local neighborhood consensus as well.
    for r in range(h):
        for c in range(w):
            counts = {}
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    rr, cc = r + dr, c + dc
                    if (dr or dc) and 0 <= rr < h and 0 <= cc < w:
                        color = grid[rr][cc]
                        counts[color] = counts.get(color, 0) + 1
            if counts and counts.get(grid[r][c], 0) <= 1:
                best = max(counts.values())
                winners = [k for k,v in counts.items() if v == best]
                if len(winners) == 1:
                    out[r][c] = winners[0]
    return out
'''
